// Illustrative monthly scenarios, not a dated bank cash-flow forecast.
function scenarioModel(months,shock){
 const income=money2(Number(state.incomeMonthly)+Number(state.planning.allowance));
 const expenses=money2(sum(state.budget.map(x=>Number(x[1])||0))+Number(state.planning.annualIrregular||0)/12);
 const allocate=money2(sum(state.allocations.map(x=>Number(x[1])||0)));
 const monthly=money2(income*(shock==='adverse'?.90:1)-expenses*(shock==='adverse'?1.10:1)-allocate);
 const start=money2(bal('free')+forecastCashBalance());
 const oneOff=shock==='adverse'?500:0;
 return {months,income,expenses,allocate,monthly,start,oneOff,ending:money2(start+months*monthly-oneOff),reserve:Math.max(0,Number(state.forecast.reserve)||0)};
}
