// v2.4.6: real savings are net registered transfers, not the income-expense cash-flow margin.
// Financial periods run from the 27th to the 26th; internal transfers do not create expenses.
function savingMetrics(){
 ensureV24();
 const key=currentFinancial(),entries=state.transactions.filter(t=>periodMatch(t,key));
 const income=sum(entries.filter(t=>t.type==='income').map(t=>Number(t.amount)||0));
 const expense=sum(entries.filter(t=>t.type==='expense').map(t=>Number(t.amount)||0));
 const ids=['emergency','leo','bianca'];
 const net=Object.fromEntries(ids.map(id=>[id,0]));
 for(const t of entries){
  if(t.type!=='transfer')continue;
  const amount=Number(t.amount)||0;
  // Only flows across the boundary between operational/future-expense funds
  // and protected savings count. Transfers among savings funds are neutral.
  const fromSaved=ids.includes(t.from),toSaved=ids.includes(t.to);
  if(fromSaved===toSaved)continue;
  if(toSaved)net[t.to]+=amount;
  else net[t.from]-=amount;
 }
 const breakdown=savingsBreakdown(),actual=sum(Object.values(net));
 return {income,expense,net,actual,planned:breakdown.savings,other:breakdown.other,
  monthlyIncome:breakdown.monthlyIncome,
  plannedRate:breakdown.monthlyIncome>0?breakdown.savings/breakdown.monthlyIncome*100:null,
  actualRate:income>0?actual/income*100:null,
  cashFlowRate:income>0?(income-expense)/income*100:null};
}
